def make_finding(raw, index):
    fid, name, description, refs, value_kind, required = raw
    kinds = KINDS[index % len(KINDS)]
    return {
        "id":fid,"name":name,"description":description,"source_refs":refs,
        "questions":[
            {"id":fid+"-q01","text":f"What identity, type, role, scope, version and values define {name.lower()}?","kind":kinds[0],"answer_data":["identifiers","types and roles","scope and version","values and explicit unknowns"]},
            {"id":fid+"-q02","text":f"Which authority, source, observation, evidence and event or effective time support {name.lower()}?","kind":kinds[1],"answer_data":["authority","source and evidence","observation method","event and effective time","confidence"]},
            {"id":fid+"-q03","text":f"How is {name.lower()} validated, shared, changed, contested, corrected and retained?","kind":kinds[2],"answer_data":["validation","access","change and dispute","lineage","retention"]},
        ],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured appointment or reservation data for "+name.lower()+".","value_kind":value_kind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing booking record for "+name.lower()+" with authority, time, provenance and access marking.","media_or_form":["logical booking assertion","booking, response, event or evidence reference"],"serial":True,"identity_strategy":"Booking identifier plus "+fid+" assertion, artifact or event identifier; party name, display date, timestamp and digest never identify the booking alone.","source_refs":refs}],
        "inline_only_rationale":None,
    }

def structure():
    cursor = 0
    bundles = []
    for bid, name, description, rationale, refs, layers in BUNDLES:
        made_layers = []
        for lid, lname, ldescription, lrefs, findings in layers:
            made = []
            for raw in findings:
                made.append(make_finding(raw, cursor))
                cursor += 1
            made_layers.append({"id":lid,"name":lname,"description":ldescription,"source_refs":lrefs,"findings":made})
        bundles.append({"id":bid,"name":name,"description":description,"rationale":rationale,"source_refs":refs,"layers":made_layers})
    return {"bundles":bundles}

